SELECT p.id, p.app_id AS appId, a.code AS appCode, a.name AS appName, p.name, p.description, p.current_version_id AS currentVersionId, p.current_version_no AS currentVersionNo, p.stage_count AS stageCount, a.repo_branch AS defaultBranch, a.owner_names AS ownerNames, p.create_time AS createTime, p.update_time AS updateTime FROM dev_pipeline p INNER JOIN dev_app a ON a.id = p.app_id AND a.is_deleted = 0
p.is_deleted = 0
AND p.id IN
#{id}
AND p.name LIKE CONCAT('%', #{query.keyword}, '%')
AND p.app_id IN
#{appId}
AND (
FIND_IN_SET(#{ownerId}, a.owner_ids) > 0
)
ORDER BY p.update_time DESC LIMIT #{limit}

SELECT COUNT(1)
FROM dev_pipeline
WHERE is_deleted = 0
  AND app_id = #{appId}
  AND name = #{name}

    AND id != #{id}
